// SCRATCH intent-coverage witness (not maintained; deleted after probe).
import { expect, test } from "../dashboardTest.ts";
import { parts } from "../dashboardPage.ts";
import { chooseProject, selectedProjectId } from "../projectChoice.ts";
import { linked, openSelectionPage } from "../recentlyDoneSelectionJourney.ts";
import { holdPygardonCatalog, isPygardonCatalog } from "../pygardonCatalogReads.ts";

test.use({ projectFolders: ["open-dough", "doughnut", "pygardon"] });

test("witness: project change supersedes an unanswered check", async ({ page, dashboard }) => {
  const { shown } = await openSelectionPage(page, dashboard);
  const { intentChoice, intent } = parts(page);
  await intentChoice.click();
  await expect(intent).toBeVisible();
  const held = await holdPygardonCatalog(page);
  const settled = new Promise<string>((resolve) => {
    page.on("requestfailed", (r) => { if (isPygardonCatalog(new URL(r.url()))) resolve("aborted"); });
    page.on("requestfinished", (r) => { if (isPygardonCatalog(new URL(r.url()))) resolve("answered"); });
  });
  await shown.entry(linked.title).click();
  await held.asked;
  await chooseProject(page, "Doughnut");
  held.release();
  const how = await settled;
  await page.waitForTimeout(2_000);
  const project = await selectedProjectId(page);
  const story = await intent.getAttribute("data-selected-story");
  const pressed = await shown.entry(linked.title).getAttribute("aria-pressed");
  console.log(`WITNESS catalogRead=${how} project=${project} selectedStory=${story} linkedPressed=${pressed}`);
  expect({ project, story }).toEqual({ project: "doughnut", story: null });
});
EOF
